style.css:
@-moz-document regexp(".*") {
html {
    background-color: #121212 !important;
  }

  body {
    background-color: #121212 !important;
    color: #e8e8e8 !important;
  }

  input,
  textarea,
  select,
  button {
    background-color: #222222 !important;
    color: #f1f1f1 !important;
  }

  a {
    color: #8ab4ff !important;
  }

  pre,
  code {
    background-color: #1e1e1e !important;
    color: #e6e6e6 !important;
  }
}
